package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValueTrue() throws IOException {
        jsonWriter.value(true);

        ArgumentCaptor<String> stringCaptor = ArgumentCaptor.forClass(String.class);
        verify(stringWriter, times(1)).write(stringCaptor.capture());
        assertEquals("true", stringCaptor.getValue());
    }

    @Test
    public void testValueFalse() throws IOException {
        jsonWriter.value(false);

        ArgumentCaptor<String> stringCaptor = ArgumentCaptor.forClass(String.class);
        verify(stringWriter, times(1)).write(stringCaptor.capture());
        assertEquals("false", stringCaptor.getValue());
    }

    @Test(expected = IOException.class)
    public void testValueIOException() throws IOException {
        doThrow(IOException.class).when(stringWriter).write(anyString());
        jsonWriter.value(true);
    }

    @Test
    public void testValueReturnsSameInstance() throws IOException {
        JsonWriter result = jsonWriter.value(true);
        assertSame(jsonWriter, result);
    }

    @Test
    public void testValueWithDeferredName() throws IOException {
        when(jsonWriter.writeDeferredName()).thenReturn(jsonWriter);
        when(jsonWriter.beforeValue(false)).thenReturn(jsonWriter);

        jsonWriter.value(true);

        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
    }

    @Test
    public void testValueWithNullWriter() throws IOException {
        StringWriter nullWriter = null;
        JsonWriter nullJsonWriter = new JsonWriter(nullWriter);

        assertThrows(NullPointerException.class, () -> nullJsonWriter.value(true));
    }
}
